function initAudio(){if(audioCtx){audioCtx.resume();return;}audioCtx=new (window.AudioContext||window.webkitAudioContext)();master=audioCtx.createGain();master.gain.value=.65;master.connect(audioCtx.destination);const noise=audioCtx.createBuffer(1,audioCtx.sampleRate*4,audioCtx.sampleRate),arr=noise.getChannelData(0);let last=0;for(let i=0;i<arr.length;i++){last=(last+(Math.random()*2-1)*.08)/1.02;arr[i]=last*3;}function loop(freq,q,gain){const s=audioCtx.createBufferSource();s.buffer=noise;s.loop=true;const f=audioCtx.createBiquadFilter();f.type='bandpass';f.frequency.value=freq;f.Q.value=q;const g=audioCtx.createGain();g.gain.value=gain;s.connect(f);f.connect(g);g.connect(master);s.start();return g;}windGain=loop(550,.3,.1);riverGain=loop(1900,.55,.25);marketGain=loop(320,1.2,.02);window.__town.audio='running';}
function note(freq,dur,gain,type='sine',end=freq){if(!audioCtx||muted)return;const o=audioCtx.createOscillator(),g=audioCtx.createGain(),now=audioCtx.currentTime;o.type=type;o.frequency.setValueAtTime(freq,now);o.frequency.exponentialRampToValueAtTime(Math.max(30,end),now+dur);g.gain.setValueAtTime(.0001,now);g.gain.exponentialRampToValueAtTime(gain,now+.012);g.gain.exponentialRampToValueAtTime(.0001,now+dur);o.connect(g);g.connect(master);o.start();o.stop(now+dur+.02);}
