function floorAt(x,z){for(const b of bridges)if(Math.abs(z-b.z)<b.hw+.06&&Math.abs(x-b.center)<=b.half)return b.top(x);return 0;}
function canMove(x,z){for(const b of bridges)if(Math.abs(x-b.center)<b.half&&Math.abs(z-b.z)>b.hw-.33&&Math.abs(z-b.z)<b.hw+.25&&player.pos.y<b.top(x)+1.18)return false;if(Math.abs(x)>276||Math.abs(z)>337)return false;if(Math.abs(x-riverX(z))<18.25&&!bridges.some(b=>Math.abs(z-b.z)<b.hw-.32&&Math.abs(x-b.center)<b.half+.2))return false;for(const b of colliders)if(Math.abs(x-b.x)<b.w+.3&&Math.abs(z-b.z)<b.d+.3&&player.pos.y<b.y+b.h&&player.pos.y+1.7>b.y)return false;return true;}
function walk(dt){player.yaw-=input.look.dx;player.pitch=Math.max(-1.43,Math.min(1.43,player.pitch-input.look.dy));const speed=input.crouch?1.8:input.sprint?6.4:3.8;let xx=input.move.x,zz=input.move.y,l=Math.hypot(xx,zz);if(l>1){xx/=l;zz/=l;}const dx=(Math.cos(player.yaw)*xx-Math.sin(player.yaw)*zz)*speed*dt,dz=(-Math.sin(player.yaw)*xx-Math.cos(player.yaw)*zz)*speed*dt,n=Math.max(1,Math.ceil(Math.hypot(dx,dz)/.16));let moved=false;for(let i=0;i<n;i++){if(canMove(player.pos.x+dx/n,player.pos.z)){player.pos.x+=dx/n;moved||=dx!==0;}if(canMove(player.pos.x,player.pos.z+dz/n)){player.pos.z+=dz/n;moved||=dz!==0;}}const y=floorAt(player.pos.x,player.pos.z);if(input.pressed('jump')&&player.grounded){player.vy=6.4;player.grounded=false;}player.vy-=21*dt;player.pos.y+=player.vy*dt;if(player.pos.y<=y+.16&&player.vy<=0){player.pos.y=y;player.vy=0;player.grounded=true;}else if(player.pos.y>y+.2)player.grounded=false;if(moved)player.bob+=dt*(input.sprint?13:9);camera.position.set(player.pos.x,player.pos.y+(input.crouch?1.05:1.68)+(moved&&player.grounded?Math.sin(player.bob)*.018:0),player.pos.z);camera.rotation.set(player.pitch,player.yaw,0,'YXZ');return moved;}
function birdCamera(dt){if(mode==='bird'){const speed=bird.radius*.35*dt;const x=(keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0),z=(keys.has('KeyS')?1:0)-(keys.has('KeyW')?1:0);bird.target.x+=x*speed;bird.target.z+=z*speed;bird.azimuth+=((keys.has('KeyQ')?1:0)-(keys.has('KeyE')?1:0))*dt*.6;bird.target.x=Math.max(-250,Math.min(250,bird.target.x));bird.target.z=Math.max(-310,Math.min(310,bird.target.z));}if(touring){bird.target.z=270-((t*.65)%540);bird.target.x=riverX(bird.target.z)-18;bird.radius=140;bird.elevation=.62;bird.azimuth=.8;}camera.position.set(bird.target.x+Math.cos(bird.azimuth)*bird.radius*Math.cos(bird.elevation),Math.sin(bird.elevation)*bird.radius,bird.target.z+Math.sin(bird.azimuth)*bird.radius*Math.cos(bird.elevation));avoidBirdClipping();camera.lookAt(bird.target);}
